# Define a function to find adjacent states in the grid world
def get_adjacent_states(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Create a dictionary mapping each state to its adjacent states
    adj_map = {}

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] != 'X':
                adjacent = []

                # Check all four cardinal directions (up, down, left, right)
                if row > 0:
                    adjacent.append(grid[row-1][col])
                if row < rows - 1:
                    adjacent.append(grid[row+1][col])
                if col > 0:
                    adjacent.append(grid[row][col-1])
                if col < cols - 1:
                    adjacent.append(grid[row][col+1])

                # Add the current state to its list of adjacent states
                adj_map[grid[row][col]] = adjacent

    return adj_map

# Define a function to group connected cells in the grid world
def get_connected_cells(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Initialize visited set and parent dictionary for DFS
    visited = set()
    parent = {}

    def dfs(state, row, col):
        if state == 'X':
            return

        visited.add(state)

        directions = [(1, 0), (-1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = row + dr, col + dc

            # Check if the new position is within bounds
            if 0 <= nr < rows and 0 <= nc < cols:
                adjacent_state = grid[nr][nc]

                # If the adjacent state has not been visited yet
                if adjacent_state not in visited:
                    parent[adjacent_state] = (state, nr, nc)
                    dfs(adjacent_state, nr, nc)

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] != 'X':
                dfs(grid[row][col], row, col)

    # Group connected cells into a list of lists
    groups = []

    for state in visited:
        group = [state]

        while parent[state]:
            state, _, _ = parent[state]
            group.append(state)

        groups.append(group)

    return groups

